\label{lem-highlow2}
   Let $G$ be a graph, $k \geq 2|E(G)|/|V(G)|$, and $q < k$. With respect to a fixed ordering of the vertices of $G$, define $V_{\operatorname*{low}} = \{v : 0 \leq \deg_G^\ell(v) < \frac{k + q}{2}\}$, and $V_{\operatorname*{high}} = \{v : \frac{k + q}{2} \leq \deg_G^\ell(v)\}$.
    Then, $|V_{\operatorname*{low}}| \geq \frac{q}{k+q}|V(G)|$.

\label{lemma:non-cutset-ordering}
  Let $G$ be a connected graph of maximum degree $\Delta$, and let $X \subseteq V(G)$ be a set of vertices such that $G - X$ is connected, and $|X| \leq \Delta$.
  Then for any $v \in V(G) \setminus X$, there exists an ordering of the vertices of $G$ with the following properties:
  \begin{enumerate}
    \item Every vertex in $X$ is to the left of any vertex in $V(G) \setminus X$.
    \item The rightmost vertex is $v$.
    \item Every vertex $u \neq v$ has $\deg_G^\ell(u) < \Delta$.
  \end{enumerate}

\label{lemma:degree-choice:main-ordering}
    Let $G$ be a connected graph which is not a Gallai tree, and let $H$ be any minimum Rubin subgraph of $G$. Then there exists an ordering $\sigma$ of $V(G)$ with the following properties.
    \begin{enumerate}
        \item Every vertex of $H$ is ordered to the left of any vertex of $G - H$.
        \item For every vertex $v$ of $G - H$, we have $\deg_G^\ell(v) \geq 1$.
        \item Let $V_{\operatorname*{low}} \coloneqq \{ v \in V(G) \setminus V(H) : \deg_G^\ell(v) \geq 2\}$. Then $|V_{\operatorname*{low}}| \geq \frac{|V(G)| - h({G}) - b({G})}{c^*({G}) - 1}$.
    \end{enumerate}

\label{lemma:partition-algo}
    Let $G$ be a graph with maximum degree $\Delta$. Given a vector of $s \geq 1$ integers $p=(p_1, \dots, p_s)$ with $p_i \geq 0$ for $i \in [s]$ and $\sum_{i=1}^s p_i = \Delta - s$ and a $(\Delta-1)$-degeneracy
    ordering $v_1, \dots, v_n$ of $V(G)$, \cref{alg:greedydegenerate} partitions $V(G)$ into sets $\{V_1, \dots, V_s\}$ so that $G[V_i]$ is $p_i$-degenerate.

\label{thm-degpart}
Let $G$ be a graph of maximum degree $\Delta$ which is not complete. Let $p=(p_1, \dots, p_s)$ be a vector of $s \geq 1$ integers with $p_1 \geq \dots \geq p_s \geq 0$, and let $q < \Delta$.
If $\sum_{i=1}^{s} p_i = \Delta - s$, then $G$ has at least $\textup{choices}_{\Delta}(p,q)^{\frac{q}{\Delta+q}|V(G)|-p_s-s-3}$ $p$-partitions.

Let $G=(V, E)$ be an instance of $s$-\textsc{Colorability}\xspace. 
    We construct an instance of $p$-\textsc{Degenerate Partitioning}\xspace with a graph $H$. 
    We initialize $H$ as the empty graph. 
    For every vertex $v$ in $G$, we add a \emph{vertex gadget}
    $S_v$ to $H$ (see Figure \ref{fig:hardness-degpart}).
    The vertex gadget $S_v$ consists of $\sum_{i=1}^s p_i+s-1$ \emph{clique} vertices which form a clique and two \emph{external} vertices $x_v$ and $y_v$ which are adjacent to every clique vertex. 
    For each edge $uv$ in $G$, we add $x_ux_v$ and $y_uy_v$ to $E(H)$. 
    We call $S_v$ and $S_u$ \emph{matched} gadgets. 
    This completes the construction. 

    Now, we compute the maximum degree of $H$. Let $v \in V(S_u)$ for a vertex gadget $S_u \subseteq H$. If $v$ is a clique vertex, then $\deg_H(v) = \sum_{i=1}^s p_i + s$. If $v$ is an external vertex, then $v$ has exactly $\sum_{i=1}^sp_i+s-1$ neighbors which are clique vertices in $S_u$ and at most $\Delta_s$ neighbors which are external vertices in vertex gadgets distinct from $S_u$. Hence, $\deg_H(v) \leq \sum_{i=1}^s p_i + s + \Delta_s = \Delta(H)$.


    We claim that $H$ is $p$-partitionable if and only if $G$ is $s$-colorable. 
    First, assume $H$ is $p$-partitionable. We will show $G$ is $s$-colorable. Let $\mathcal{P}$ be a $p$-partition of $V(H)$ into sets $V_1, \dots, V_s$. We begin by proving some important claims about the vertex gadget.

